"""Congruence-of-Squares Splitting Procedure.

Given a modulus N > 1 and integers x, y witnessing x^2 = y^2 (mod N) with
x != +-y (mod N), return a divisor of N strictly between 1 and N.
"""

from __future__ import annotations

import math
from typing import Optional, Tuple


def is_nontrivial_divisor(n: int, d: int) -> bool:
    """Return True iff d divides n and 1 < d < n."""
    return n % d == 0 and 1 < d < n


def split_from_congruence(n: int, x: int, y: int) -> Optional[Tuple[int, int]]:
    """Split n using a congruence of squares.

    Preconditions checked at runtime:
        n > 1,  n | (x - y)(x + y),  n does not divide x - y,  n does not
        divide x + y.
    Returns (d, n // d) with 1 < d < n, or None if the hypotheses fail.

    Complexity: one Euclidean gcd, O(log^2 n) bit operations.
    """
    if n <= 1:
        return None
    if (x * x - y * y) % n != 0:
        return None
    if (x - y) % n == 0 or (x + y) % n == 0:
        return None
    d = math.gcd(x - y, n)
    if not is_nontrivial_divisor(n, d):
        return None
    return d, n // d


def search_congruence(n: int, limit: int = 2000) -> Optional[Tuple[int, int, int, int]]:
    """Brute-force search for a usable congruence of squares modulo n.

    Returns (x, y, d, n // d) for the first witness found, else None.
    This search is the EXPENSIVE half; the split itself is the cheap half.
    Complexity: O(limit^2) modular multiplications in the worst case.
    """
    squares = {}
    for x in range(2, min(n, limit)):
        s = (x * x) % n
        if s in squares:
            y = squares[s]
            result = split_from_congruence(n, x, y)
            if result is not None:
                return (x, y, result[0], result[1])
        else:
            squares[s] = x
    return None


if __name__ == "__main__":
    for modulus in (1649, 8051, 10403, 1000003 * 17):
        found = search_congruence(modulus)
        if found is None:
            print(f"N = {modulus}: no witness within the search bound")
        else:
            x, y, d, e = found
            print(f"N = {modulus}: x = {x}, y = {y} -> {d} * {e}")
